// Campaign artwork and prices as published on Unicars' offers page; no live stock connection.
window.uniCampaigns=[
{id:'tiguan',brand:'Volkswagen',model:'Tiguan',title:'Everyday. Upgraded.',price:29900,detail:'Published from €29,900, including a €6,000 anniversary bonus.',image:'offer-tiguan.webp',source:'https://www.unicars.com/gr/vw-tiguan-campaign.php'},
{id:'taigo',brand:'Volkswagen',model:'Taigo & T-Cross',title:'Make room for adventure.',price:null,detail:'Published campaign: up to €4,000 off. Ask about the eligible version.',image:'offer-taigo.webp',source:'https://www.unicars.com/gr/vw-suv-taigo-t-cross.php'},
{id:'kodiaq',brand:'Škoda',model:'Kodiaq',title:'Space for your kind of life.',price:32900,detail:'Published Selection Package campaign from €32,900.',image:'offer-kodiaq.webp',source:'https://www.unicars.com/gr/offers-sales.php'},
{id:'audiq3',brand:'Audi',model:'Q3',title:'A different perspective.',price:37900,detail:'Published Signature Package campaign at €37,900.',image:'offer-audiq3.webp',source:'https://www.unicars.com/gr/offers-sales.php'},
{id:'raval',brand:'CUPRA',model:'Raval',title:'Meet your electric side.',price:null,detail:'Discover the new all-electric CUPRA Raval campaign.',image:'offer-raval.webp',source:'https://www.unicars.com/gr/offers-sales.php'}];
const homeArrow='<svg aria-hidden="true"><use href="#arrow"/></svg>';
const homeFaq={Buying:[['How do I find out more about an offer?','Open a campaign to view the original artwork, its published details and an enquiry form. The Unicars team can confirm the applicable version, final price, terms and availability.'],['Can I explore cars without choosing a brand first?','Yes. Explore vehicles lets you browse the model range, SUVs, electric, hybrid and commercial vehicles. Choose eHub - Available cars under Explore vehicles for discounted-vehicle and stock enquiries.'],['Does an enquiry reserve the vehicle?','An enquiry is a request for information. A vehicle or appointment is only confirmed after the Unicars team contacts you. This prototype does not send enquiries.']],Electric:[['Where do I start with electric ownership?','Start with your usual journeys and charging options. Explore the EV guidance for information about everyday use, home charging and the public charging network.'],['Where can I find a Unicars charger?','Use Find a charger under Electric vehicles to reach the charging-map destination. Live charger data is not connected in this prototype.']],Ownership:[['How can I arrange a service?','Use Book a service in Support, or the service action below, to request an appointment. The team must confirm the date and location. The prototype demonstrates the request only.'],['Where can I check warranty information?','Choose Warranty information under Support. Coverage depends on your vehicle and applicable terms, so check the relevant documents or ask the team.']]};
window.renderUniHome=()=>`<div class="uni-home">
<section class="campaign-hero"><div class="home-frame hero-intro"><h1>Your next chapter.</h1><div><p>A new car. A fresh possibility.<br>Find the offer that moves you.</p><a class="home-btn light" href="#home-offers" data-home-scroll="home-offers">Explore the offers ${homeArrow}</a></div></div></section>
<nav class="brand-ribbon home-frame" aria-label="Explore by brand">${[['Volkswagen','brand-vw','volkswagen'],['Audi','brand-audi','audi'],['Škoda','brand-skoda','skoda'],['CUPRA','brand-cupra','cupra'],['SEAT','brand-seat','seat']].map(([n,r,logo],i)=>`<a class="brand-logo-link brand-logo-${logo}" href="#${r}" aria-label="Explore ${n} vehicles" style="--brand-delay:${i*70}ms"><span class="brand-logo-stage"><img src="assets/brands/${logo}.svg" alt="${n}" width="120" height="72"></span><span class="brand-logo-caption">Explore vehicles ${homeArrow}</span></a>`).join('')}</nav>
<section class="home-offers home-frame" id="home-offers"><div class="home-heading"><h2>Offers worth<br>exploring.</h2><div><p>Find an offer by brand, compare the details and take your next step.</p><a class="home-text-link" href="#prices">Price lists & brochures ${homeArrow}</a></div></div><div class="campaign-controls" role="group" aria-label="Filter vehicle offers">${['All offers','Volkswagen','Škoda','Audi','CUPRA'].map((n,i)=>`<button data-offer-filter="${n}" aria-pressed="${i===0}">${n}</button>`).join('')}<span id="offerCount" role="status">5 campaigns</span></div>${campaignNavigation()}<div class="campaign-gallery" id="campaignGallery" tabindex="0" role="region" aria-label="Vehicle offers">${window.uniCampaigns.map(c=>campaignCard(c)).join('')}</div><p class="campaign-note">Original campaign artwork from Unicars. Prices and promotions shown are subject to their published terms and confirmation by the team.</p></section>
<section class="home-finder"><div class="home-frame"><div class="finder-grid"><div class="finder-story"><img src="assets/sales.webp" alt="CUPRA on a mountain road" loading="lazy"><div><h2>Find your<br>next move.</h2><p>A favourite brand. A price in mind.<br>Let’s find your starting point.</p><a class="home-text-link" href="#cars">Explore all models ${homeArrow}</a></div></div><form id="homeFinder"><fieldset class="finder-brand-field"><legend>Which brand feels like you?</legend><p class="finder-hint">Choose a favourite, or keep your options open.</p><div class="finder-brand-choices"><label class="finder-brand-choice"><input type="radio" name="brand" value="any" checked><span><strong>All brands</strong><small>Open to ideas</small></span></label>${[['Volkswagen','volkswagen'],['Audi','audi'],['Škoda','skoda'],['CUPRA','cupra'],['SEAT','seat']].map(([name,logo])=>`<label class="finder-brand-choice"><input type="radio" name="brand" value="${name}"><span><img src="assets/brands/${logo}.svg" alt="" width="64" height="34"><strong>${name}</strong></span></label>`).join('')}</div></fieldset><fieldset class="finder-price-field"><legend>What starting price works for you?</legend><div class="finder-budget-choices">${[['any','Any price'],['35000','Up to €35,000'],['over','Above €35,000']].map(([v,l],i)=>`<label><input type="radio" name="budget" value="${v}" ${i===0?'checked':''}><span>${l}</span></label>`).join('')}</div><p class="finder-hint">Filters use published campaign starting prices.</p></fieldset><button class="home-btn blue finder-submit" type="submit"><span>Show 5 offers</span>${homeArrow}</button><div id="finderResults" class="finder-results" aria-live="polite"></div><small class="finder-disclosure">Published offers, subject to terms and confirmation. Stock and finance are not connected.</small></form></div></div></section>
<section class="electric-feature home-frame"><div class="electric-image"><img loading="lazy" src="assets/offer-raval.webp" alt="Official new CUPRA Raval all-electric campaign poster"></div><div class="electric-copy"><h2>A new kind<br>of everyday.</h2><p>Curious about electric? Start with the questions that matter: your journeys, charging at home, and where to plug in along the way.</p><div class="electric-tabs" role="group" aria-label="Electric ownership topics"><button data-ev-topic="daily" aria-pressed="true">Everyday driving</button><button data-ev-topic="home" aria-pressed="false">Home charging</button><button data-ev-topic="away" aria-pressed="false">On the road</button></div><div id="evTopic" aria-live="polite"><h3>Start with your routine.</h3><p>Think about your daily distance, longer journeys and parking. Our team can help you explore a model that suits your needs.</p><a class="home-text-link" href="#ev-ownership">Explore electric ownership ${homeArrow}</a></div></div></section>
<section class="home-care"><div class="home-frame care-grid"><div><h2>The next chapter.<br>And every one after.</h2><p>Already driving a Unicars vehicle? Get to the right service, information or team in a few clear steps.</p><div class="care-actions"><button class="home-btn light" data-action="service">Book a service ${homeArrow}</button><a class="home-btn ghost" href="#owners">Explore support ${homeArrow}</a></div></div><a class="care-art" href="#care"><img loading="eager" width="1200" height="1034" src="assets/offer-care.webp" alt="Unicars Care Plan published maintenance campaign from €179, subject to terms"><span>Discover Unicars Care Plan ${homeArrow}</span></a></div></section>
<section class="home-faq home-frame"><div><h2>A few good<br>questions.</h2><p>Clear answers for your next step.</p><a class="home-text-link" href="#contact">Talk to the team ${homeArrow}</a></div><div><div class="faq-switch" role="group" aria-label="Question topics">${Object.keys(homeFaq).map((n,i)=>`<button data-faq-topic="${n}" aria-pressed="${i===0}">${n}</button>`).join('')}</div><div id="homeFaqItems">${faqMarkup('Buying')}</div></div></section>
<div class="home-frame home-source-note">Homepage concept · Campaign artwork sourced from <a href="https://www.unicars.com/gr/offers-sales.php" target="_blank" rel="noopener">Unicars offers</a>. Hero footage: <a href="https://www.skoda-storyboard.com/en/press-kits/skoda-elroq-press-kit/videos/attachment/skoda_elroq_footage_82fe9e6d/" target="_blank" rel="noopener">Škoda Auto</a>. Enquiries are demonstration only.</div></div>`;
function campaignNavigation(){return `<div class="campaign-navigation" aria-label="Browse offers"><button type="button" data-offer-step="-1" aria-controls="campaignGallery" disabled>${homeArrow}<span>Previous</span></button><span class="campaign-position" role="status" aria-live="polite" aria-atomic="true">1 of 5</span><button type="button" data-offer-step="1" aria-controls="campaignGallery"><span>Next</span>${homeArrow}</button></div>`}
function campaignState(gallery){const cards=[...gallery.querySelectorAll('article')].filter(card=>!card.hidden);const max=Math.max(0,gallery.scrollWidth-gallery.clientWidth);let index=0;if(cards.length){const origin=cards[0].offsetLeft;index=cards.reduce((best,card,i)=>Math.abs(card.offsetLeft-origin-gallery.scrollLeft)<Math.abs(cards[best].offsetLeft-origin-gallery.scrollLeft)?i:best,0);if(max>2&&gallery.scrollLeft>=max-2)index=cards.length-1;}return {cards,index,max};}
function updateCampaignNavigation(){const gallery=document.getElementById('campaignGallery');if(!gallery)return;const controls=gallery.previousElementSibling;if(!controls?.classList.contains('campaign-navigation'))return;const {cards,index,max}=campaignState(gallery);controls.querySelector('[data-offer-step="-1"]').disabled=gallery.scrollLeft<=2||cards.length<2;controls.querySelector('[data-offer-step="1"]').disabled=gallery.scrollLeft>=max-2||cards.length<2;controls.querySelector('.campaign-position').textContent=cards.length?`${index+1} of ${cards.length}`:'No offers';}
function stepCampaign(direction){const gallery=document.getElementById('campaignGallery');if(!gallery)return;const {cards,index}=campaignState(gallery);const card=cards[Math.max(0,Math.min(cards.length-1,index+direction))];if(!card)return;gallery.scrollTo({left:card.offsetLeft-cards[0].offsetLeft,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}
document.addEventListener('click',event=>{const button=event.target.closest('[data-offer-step]');if(button)stepCampaign(Number(button.dataset.offerStep));});
document.addEventListener('keydown',event=>{if(event.target.id!=='campaignGallery'||!matchMedia('(max-width:600px)').matches)return;if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();stepCampaign(event.key==='ArrowLeft'?-1:1);}});
document.addEventListener('scroll',event=>{if(event.target.id==='campaignGallery')updateCampaignNavigation();},true);
window.addEventListener('resize',updateCampaignNavigation);
new MutationObserver(()=>requestAnimationFrame(updateCampaignNavigation)).observe(document.getElementById('main'),{childList:true});
function campaignCard(c){return `<article class="campaign-card" data-brand="${c.brand}"><button class="poster-button" data-campaign="${c.id}" aria-label="Explore ${c.brand} ${c.model} campaign"><img loading="lazy" src="${window.uniAsset('assets/'+c.image)}" alt="Official ${c.brand} ${c.model} offer poster" width="2487" height="2194"></button><div class="campaign-card-caption"><p class="campaign-brand">${c.brand}</p><h3>${c.model}</h3><p class="campaign-detail">${c.detail}</p><button class="campaign-view" data-campaign="${c.id}" aria-label="View ${c.model} offer">View offer ${homeArrow}</button></div></article>`}

function faqMarkup(topic){return homeFaq[topic].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}
let campaignOpener=null;
function openCampaign(id){campaignOpener=document.activeElement;const c=window.uniCampaigns.find(c=>c.id===id);if(!c)return;let d=document.getElementById('campaignDialog');if(!d){d=document.createElement('dialog');d.id='campaignDialog';document.body.append(d);d.addEventListener('click',e=>{if(e.target===d)d.close()});d.addEventListener('close',()=>{document.body.classList.remove('campaign-modal-open');campaignOpener?.focus()});}d.innerHTML=`<button class="campaign-close" aria-label="Close offer">×</button><div class="campaign-dialog-grid"><div class="dialog-poster"><img src="${window.uniAsset('assets/'+c.image)}" alt="Original ${c.brand} ${c.model} campaign poster"><a href="${c.source}" target="_blank" rel="noopener">View published campaign ${homeArrow}</a></div><div class="campaign-enquiry"><p>${c.brand}</p><h2>${c.model}</h2><p>${c.detail}</p><small>Published campaign. The team must confirm final pricing, eligibility, terms and availability.</small><form id="campaignEnquiry"><fieldset><legend>What would you like to do?</legend><label class="intent-option"><input type="radio" name="intent" value="details" checked> Ask about this offer</label><label class="intent-option"><input type="radio" name="intent" value="drive"> Request a test drive</label></fieldset><label>Your name<input name="name" autocomplete="name" required placeholder="Full name"></label><label>Email address<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label>Preferred location<select name="city" required><option value="">Choose a location</option>${['Nicosia','Limassol','Larnaca','Paphos','Paralimni'].map(n=>`<option>${n}</option>`).join('')}</select></label><p class="form-disclosure">Interactive prototype: nothing is sent or saved. The live team would contact you to confirm your request.</p><button class="home-btn blue" type="submit">Preview my enquiry ${homeArrow}</button><p id="campaignSuccess" role="status" hidden></p></form></div></div>`;d.querySelector('.campaign-close').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();const status=d.querySelector('#campaignSuccess');status.hidden=false;status.textContent='Enquiry preview complete for '+c.brand+' '+c.model+'. No details have been sent.';d.querySelector('button[type=submit]').disabled=true;};document.body.classList.add('campaign-modal-open');d.showModal();}
document.addEventListener('click',e=>{const campaign=e.target.closest('[data-campaign]');if(campaign){openCampaign(campaign.dataset.campaign);return;}const scroll=e.target.closest('[data-home-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.homeScroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});return;}const filter=e.target.closest('[data-offer-filter]');if(filter){document.querySelectorAll('[data-offer-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===filter)));let n=0;document.querySelectorAll('#campaignGallery article').forEach(a=>{a.hidden=filter.dataset.offerFilter!=='All offers'&&a.dataset.brand!==filter.dataset.offerFilter;if(!a.hidden)n++});document.getElementById('offerCount').textContent=n+' campaign'+(n===1?'':'s');document.getElementById('campaignGallery').scrollTo({left:0,behavior:'instant'});requestAnimationFrame(updateCampaignNavigation);return;}const faq=e.target.closest('[data-faq-topic]');if(faq){document.querySelectorAll('[data-faq-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b===faq)));document.getElementById('homeFaqItems').innerHTML=faqMarkup(faq.dataset.faqTopic);}const ev=e.target.closest('[data-ev-topic]');if(ev){document.querySelectorAll('[data-ev-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b===ev)));const topics={daily:['Start with your routine.','Think about your daily distance, longer journeys and parking. Our team can help you explore a model that suits your needs.','Explore electric ownership','ev-ownership'],home:['Make charging part of home.','Explore installation requirements, electricity costs and compatible charging options before choosing your setup.','Learn about home charging','charging'],away:['Know where to plug in.','Find Unicars charging locations and plan charging stops around your journey.','Find a charger','chargers']};const [h,p,l,r]=topics[ev.dataset.evTopic];document.getElementById('evTopic').innerHTML=`<h3>${h}</h3><p>${p}</p><a class="home-text-link" href="#${r}">${l}${homeArrow}</a>`;}});
function finderMatches(form){const f=new FormData(form),budget=f.get('budget');return window.uniCampaigns.filter(c=>(f.get('brand')==='any'||c.brand===f.get('brand'))&&(budget==='any'||c.price&&(budget==='over'?c.price>35000:c.price<=35000)))}
document.addEventListener('change',e=>{const form=e.target.closest('#homeFinder');if(!form)return;const count=finderMatches(form).length;form.querySelector('.finder-submit span').textContent=count?'Show '+count+' offer'+(count===1?'':'s'):'Explore options';document.getElementById('finderResults').innerHTML=''});
document.addEventListener('submit',e=>{if(e.target.id!=='homeFinder')return;e.preventDefault();const matches=finderMatches(e.target),results=document.getElementById('finderResults');results.innerHTML=matches.length?`<h3>${matches.length} offer${matches.length===1?'':'s'} for your shortlist</h3>`+matches.map(c=>`<button type="button" data-campaign="${c.id}" aria-label="Explore ${c.brand} ${c.model} offer"><img src="${window.uniAsset('assets/'+c.image)}" alt=""><span><strong>${c.brand} ${c.model}</strong><small>${c.price?'Published from €'+c.price.toLocaleString('en-GB'):'View campaign details'}</small></span>${homeArrow}</button>`).join(''):`<h3>Let’s explore the range.</h3><p>No published offer matches these choices. Try another price range or browse all models.</p><a class="home-text-link" href="#cars">Browse all models ${homeArrow}</a>`;results.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})});

window.renderUniOffers=()=>`<div class="uni-home"><section class="home-offers home-frame"><div class="home-heading"><h1 style="font-size:clamp(42px,5vw,72px);line-height:1.05">Explore car offers.</h1><div><p>Find a campaign worth a closer look. Open an offer to see the original artwork and ask the team about the details.</p></div></div><div class="campaign-controls" role="group" aria-label="Filter vehicle offers">${['All offers','Volkswagen','Škoda','Audi','CUPRA'].map((n,i)=>`<button data-offer-filter="${n}" aria-pressed="${i===0}">${n}</button>`).join('')}<span id="offerCount" role="status">5 campaigns</span></div>${campaignNavigation()}<div class="campaign-gallery" id="campaignGallery" tabindex="0" role="region" aria-label="Vehicle offers">${window.uniCampaigns.map(c=>campaignCard(c)).join('')}</div><p class="campaign-note">Published campaigns from Unicars. Terms, prices and availability require confirmation. Enquiries are demonstration only.</p></section></div>`;

window.renderUniBrand=(brand,models)=>{const slug={Volkswagen:'volkswagen',Audi:'audi','Škoda':'skoda',CUPRA:'cupra',SEAT:'seat'}[brand];return `<div class="uni-home"><section class="brand-listing home-frame"><p class="brand-breadcrumb"><a href="#brands">Our brands</a> / ${brand}</p><div class="brand-listing-heading"><div><h1>Explore ${brand} models.</h1><p>Choose a model to see its details and take your next step.</p></div><img src="assets/brands/${slug}.svg" alt="${brand}" width="140" height="90"></div><div class="brand-model-grid">${models.filter(([name])=>name.startsWith(brand+' ')).map(([name,id])=>`<a href="#model-${id}"><span><small>${brand}</small><h2>${name.slice(brand.length+1)}</h2><p>Explore model</p></span>${homeArrow}</a>`).join('')}</div><div class="brand-listing-actions"><a class="home-btn blue" href="#available">Explore available vehicles ${homeArrow}</a><a class="home-btn" href="#prices">Price lists & brochures ${homeArrow}</a></div><p class="campaign-note">Selected models demonstrate the proposed brand-to-model journey. This prototype does not represent a complete current model or stock catalogue.</p></section></div>`};
